Object.assign(SNIP,{});PRESET_NOTES["l74"]={"Ví dụ: Ngoặc hợp lệ": "Dấu hiệu “mở – đóng lồng nhau” gợi ý ngăn xếp: ngoặc đóng phải khớp với ngoặc mở gần nhất chưa đóng. Ba cách sai: đóng sai loại, đóng khi rỗng, còn dư ngoặc mở.", "Ví dụ: Phần tử lớn hơn tiếp theo": "Ngăn xếp đơn điệu: mỗi chỉ số vào và ra đúng một lần nên O(n), thay vì O(n²) khi nhìn sang phải từng phần tử. Phần tử không có ai lớn hơn bên phải giữ −1.", "Ví dụ: Mê cung ngắn nhất": "“Ít bước nhất” trên lưới, mọi bước như nhau: BFS. Từ S (0, 0) tới E (2, 3) cần 5 bước, vòng xuống dưới bức tường.", "Ví dụ: Dãy con tăng dài nhất O(n log n)": "Ví dụ 1, 4, 5, 9 hoặc 1, 4, 5, 6: độ dài 4. Bài 45 làm O(n²); mảng duoi luôn tăng nên dùng được tìm kiếm nhị phân, còn O(n log n). Lưu ý duoi không phải là một dãy con thật.", "Lỗi: tham lam cho bài đổi tiền": "In 3 2. Tham lam chỉ đúng với một số bộ mệnh giá đặc biệt (như 1, 2, 5, 10, …). Gặp đề mới, đừng tin tham lam khi chưa chứng minh hay đối chiếu với trâu bò."};EX_HINTS["l74"]=[["Số phòng cần = số cuộc họp diễn ra cùng lúc nhiều nhất. Mức chồng lấn lớn nhất luôn đạt tại một thời điểm bắt đầu nào đó.", "Sắp riêng mảng giờ bắt đầu và mảng giờ kết thúc; quét giờ bắt đầu tăng dần, trước đó trả lại mọi phòng có e ≤ s hiện tại (hai con trỏ). Hoặc dùng hàng đợi ưu tiên giữ giờ kết thúc.", "Trâu bò để đối chiếu: với mỗi s_i, đếm số cuộc họp chứa s_i — O(n²)."], ["QHĐ O(n²) của bài 45 quá chậm với n = 2·10^5. Giữ duoi[k] = phần tử cuối nhỏ nhất của một dãy tăng độ dài k + 1; duoi luôn tăng.", "Với mỗi x: tìm vị trí đầu tiên trong duoi có giá trị ≥ x (lower_bound). Không có thì nối x vào cuối; có thì thay bằng x.", "Tăng ngặt nên dùng lower_bound (≥ x); nếu đề cho phép bằng nhau (không giảm) thì dùng upper_bound. Đáp án là độ dài duoi."], ["“Ít bước nhất”, mọi bước như nhau: BFS từ ô S. d[r][c] = −1 nghĩa là chưa tới; E không tới được thì d giữ −1 — đúng đáp án cần in.", "Bốn hướng: dùng hai mảng dr, dc. Kiểm tra ra ngoài lưới trước khi đọc g[nr][nc].", "Hàng đợi lưu một số r · C + c (hoặc cặp). DFS không cho đường ngắn nhất."]];
