/* Bài 74 · Dự án cuối khóa: bộ đề luyện thi và phỏng vấn tổng hợp
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR74=[{label:"Ví dụ: Ngoặc hợp lệ",input:"",code:"#include <iostream>\n#include <stack>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nbool hopLe(const string& s) {\n    stack<char> st;\n    for (char c : s) {\n        if (c == '(' || c == '[' || c == '{') st.push(c);\n        else {\n            if (st.empty()) return false;    // đóng mà không có gì để khớp\n            char m = st.top();\n            st.pop();\n            if ((c == ')' && m != '(') || (c == ']' && m != '[') || (c == '}' && m != '{')) return false;\n        }\n    }\n    return st.empty();                 // còn ngoặc mở chưa đóng thì sai\n}\n\nint main() {\n    string ds[] = {\"([]{})\", \"([)]\", \"((\", \"}\"};\n    for (const string& s : ds) cout << s << \" \" << (hopLe(s) ? \"hop le\" : \"sai\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"st"},{type:"vars",names:["c","m"]}],py:{code:"def hop_le(s):\n    cap = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\n    st = []\n    for c in s:\n        if c in \"([{\":\n            st.append(c)\n        else:\n            if not st:                 # đóng mà không có gì để khớp\n                return False\n            if st.pop() != cap[c]:\n                return False\n    return not st                      # còn ngoặc mở chưa đóng thì sai\n\nfor s in [\"([]{})\", \"([)]\", \"((\", \"}\"]:\n    print(s, \"hop le\" if hop_le(s) else \"sai\")"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static bool HopLe(string s)\n    {\n        var st = new Stack<char>();\n        foreach (char c in s)\n        {\n            if (c == '(' || c == '[' || c == '{') st.Push(c);\n            else\n            {\n                if (st.Count == 0) return false;   // đóng mà không có gì để khớp\n                char m = st.Pop();\n                if ((c == ')' && m != '(') || (c == ']' && m != '[') || (c == '}' && m != '{')) return false;\n            }\n        }\n        return st.Count == 0;              // còn ngoặc mở chưa đóng thì sai\n    }\n\n    static void Main()\n    {\n        string[] ds = { \"([]{})\", \"([)]\", \"((\", \"}\" };\n        foreach (string s in ds) Console.WriteLine(s + \" \" + (HopLe(s) ? \"hop le\" : \"sai\"));\n    }\n}"}},{label:"Ví dụ: Phần tử lớn hơn tiếp theo",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 1, 2, 4, 3};\n    int n = a.size();\n    vector<int> kq(n, -1), st;         // st: chỉ số chưa tìm được phần tử lớn hơn\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && a[st.back()] < a[i]) {   // a[i] là đáp án của các phần tử nhỏ hơn đang chờ\n            kq[st.back()] = a[i];\n            st.pop_back();\n        }\n        st.push_back(i);\n    }\n    for (int x : kq) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"st"},{type:"cells",of:"kq"}],py:{code:"a = [2, 1, 2, 4, 3]\nn = len(a)\nkq = [-1] * n\nst = []                                # chỉ số chưa tìm được phần tử lớn hơn\nfor i in range(n):\n    while st and a[st[-1]] < a[i]:     # a[i] là đáp án của các phần tử nhỏ hơn đang chờ\n        kq[st.pop()] = a[i]\n    st.append(i)\nprint(*kq)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 1, 2, 4, 3 };\n        int n = a.Length;\n        int[] kq = new int[n];\n        for (int i = 0; i < n; i++) kq[i] = -1;\n        var st = new List<int>();              // chỉ số chưa tìm được phần tử lớn hơn\n        for (int i = 0; i < n; i++)\n        {\n            while (st.Count > 0 && a[st[st.Count - 1]] < a[i])   // a[i] là đáp án của các phần tử nhỏ hơn đang chờ\n            {\n                kq[st[st.Count - 1]] = a[i];\n                st.RemoveAt(st.Count - 1);\n            }\n            st.Add(i);\n        }\n        Console.WriteLine(string.Join(\" \", kq));\n    }\n}"}},{label:"Ví dụ: Mê cung ngắn nhất",input:"",code:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"S.#.\", \"..#.\", \"...E\", \"#...\"};\n    int R = g.size(), C = g[0].size();\n    vector<vector<int>> d(R, vector<int>(C, -1));   // số bước từ S, -1 = chưa tới\n    vector<int> hang;                  // hàng đợi BFS lưu r * C + c\n    d[0][0] = 0;\n    hang.push_back(0);\n    int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};\n    for (int i = 0; i < (int)hang.size(); i++) {\n        int r = hang[i] / C, c = hang[i] % C;\n        for (int k = 0; k < 4; k++) {\n            int nr = r + dr[k], nc = c + dc[k];\n            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;   // ra ngoài lưới\n            if (g[nr][nc] == '#' || d[nr][nc] != -1) continue;      // tường hoặc đã thăm\n            d[nr][nc] = d[r][c] + 1;\n            hang.push_back(nr * C + nc);\n        }\n    }\n    cout << d[2][3] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"d",ptr:["r","c"]}],py:{code:"g = [\"S.#.\", \"..#.\", \"...E\", \"#...\"]\nR, C = len(g), len(g[0])\nd = [[-1] * C for _ in range(R)]       # số bước từ S, -1 = chưa tới\nd[0][0] = 0\nhang = [(0, 0)]                        # hàng đợi BFS\nfor r, c in hang:\n    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):\n        nr, nc = r + dr, c + dc\n        if not (0 <= nr < R and 0 <= nc < C):   # ra ngoài lưới\n            continue\n        if g[nr][nc] == \"#\" or d[nr][nc] != -1: # tường hoặc đã thăm\n            continue\n        d[nr][nc] = d[r][c] + 1\n        hang.append((nr, nc))\nprint(d[2][3])"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] g = { \"S.#.\", \"..#.\", \"...E\", \"#...\" };\n        int R = g.Length, C = g[0].Length;\n        int[][] d = new int[R][];              // số bước từ S, -1 = chưa tới\n        for (int r = 0; r < R; r++) { d[r] = new int[C]; for (int c = 0; c < C; c++) d[r][c] = -1; }\n        var hang = new List<int> { 0 };        // hàng đợi BFS lưu r * C + c\n        d[0][0] = 0;\n\n        int[] dr = { -1, 1, 0, 0 }, dc = { 0, 0, -1, 1 };\n        for (int i = 0; i < hang.Count; i++)\n        {\n            int r = hang[i] / C, c = hang[i] % C;\n            for (int k = 0; k < 4; k++)\n            {\n                int nr = r + dr[k], nc = c + dc[k];\n                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;   // ra ngoài lưới\n                if (g[nr][nc] == '#' || d[nr][nc] != -1) continue;      // tường hoặc đã thăm\n                d[nr][nc] = d[r][c] + 1;\n                hang.Add(nr * C + nc);\n            }\n        }\n        Console.WriteLine(d[2][3]);\n    }\n}"}},{label:"Ví dụ: Dãy con tăng dài nhất O(n log n)",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};\n    vector<int> duoi;                  // duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\n    for (int x : a) {\n        auto it = lower_bound(duoi.begin(), duoi.end(), x);   // vị trí đầu tiên >= x\n        if (it == duoi.end()) duoi.push_back(x);   // nối dài dãy tăng dài nhất\n        else *it = x;                  // thay để đuôi nhỏ hơn: dễ nối tiếp sau này\n    }\n    cout << duoi.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"cells",of:"duoi"},{type:"vars",names:["x"]}],py:{code:"from bisect import bisect_left\n\na = [3, 1, 4, 1, 5, 9, 2, 6]\nduoi = []                              # duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\nfor x in a:\n    k = bisect_left(duoi, x)           # vị trí đầu tiên >= x\n    if k == len(duoi):\n        duoi.append(x)                 # nối dài dãy tăng dài nhất\n    else:\n        duoi[k] = x                    # thay để đuôi nhỏ hơn: dễ nối tiếp sau này\nprint(len(duoi))"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static int ViTriDau(List<long> d, long x)   // vị trí đầu tiên có d[k] >= x (d tăng dần)\n    {\n        int lo = 0, hi = d.Count;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (d[mid] >= x) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n\n    static void Main()\n    {\n        long[] a = { 3, 1, 4, 1, 5, 9, 2, 6 };\n        var duoi = new List<long>();           // duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\n        foreach (long x in a)\n        {\n            int k = ViTriDau(duoi, x);\n            if (k == duoi.Count) duoi.Add(x);  // nối dài dãy tăng dài nhất\n            else duoi[k] = x;                  // thay để đuôi nhỏ hơn: dễ nối tiếp sau này\n        }\n        Console.WriteLine(duoi.Count);\n    }\n}"}},{label:"Lỗi: tham lam cho bài đổi tiền",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> menhGia = {4, 3, 1};   // xếp giảm dần\n    int tien = 6, soTo = 0, con = tien;\n    for (int m : menhGia)\n        while (con >= m) { con -= m; soTo++; }   // SAI: luôn lấy tờ lớn nhất có thể\n    vector<int> dp(tien + 1, 1000000); // đúng: quy hoạch động\n    dp[0] = 0;\n    for (int s = 1; s <= tien; s++)\n        for (int m : menhGia)\n            if (m <= s) dp[s] = min(dp[s], dp[s - m] + 1);\n    cout << soTo << \" \" << dp[tien] << \"\\n\";   // tham lam 3 tờ (4+1+1), tối ưu 2 tờ (3+3)\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["s"]},{type:"vars",names:["m","con","soTo"]}],py:{code:"menh_gia = [4, 3, 1]                   # xếp giảm dần\ntien = 6\nso_to, con = 0, tien\nfor m in menh_gia:\n    while con >= m:                    # SAI: luôn lấy tờ lớn nhất có thể\n        con -= m\n        so_to += 1\ndp = [10 ** 6] * (tien + 1)            # đúng: quy hoạch động\ndp[0] = 0\nfor s in range(1, tien + 1):\n    for m in menh_gia:\n        if m <= s:\n            dp[s] = min(dp[s], dp[s - m] + 1)\nprint(so_to, dp[tien])                 # tham lam 3 tờ (4+1+1), tối ưu 2 tờ (3+3)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] menhGia = { 4, 3, 1 };           // xếp giảm dần\n        int tien = 6, soTo = 0, con = tien;\n        foreach (int m in menhGia)\n            while (con >= m) { con -= m; soTo++; }   // SAI: luôn lấy tờ lớn nhất có thể\n        int[] dp = new int[tien + 1];          // đúng: quy hoạch động\n        for (int s = 1; s <= tien; s++)\n        {\n            dp[s] = 1000000;\n            foreach (int m in menhGia)\n                if (m <= s) dp[s] = Math.Min(dp[s], dp[s - m] + 1);\n        }\n        Console.WriteLine(soTo + \" \" + dp[tien]);   // tham lam 3 tờ (4+1+1), tối ưu 2 tờ (3+3)\n    }\n}"}}];
