makeEx2(document.getElementById("ex-l74"),sim74,[{t:"Phòng họp",d:"Có n cuộc họp, cuộc thứ i diễn ra trong khoảng thời gian [s_i, e_i) (bắt đầu lúc s_i, kết thúc ngay trước e_i — một cuộc kết thúc lúc 10 và một cuộc bắt đầu lúc 10 dùng chung phòng được). Cần ít nhất bao nhiêu phòng để mọi cuộc họp đều có phòng? Đầu vào: n (1 ≤ n ≤ 2·10^5) rồi n dòng s e (0 ≤ s < e ≤ 10^9). Đầu ra: một số.",tests:[{in:"4\n9 10\n9 12\n10 11\n11 12",out:"2"},{in:"1\n1 2",out:"1"},{in:"4\n1 5\n2 6\n3 7\n4 8",out:"4"},{in:"3\n1 2\n2 3\n3 4",out:"1"},{in:"3\n0 1000000000\n0 1000000000\n0 1000000000",out:"3"},{in:"40\n78 111\n14 35\n15 35\n23 37\n44 52\n56 86\n67 85\n57 68\n40 58\n64 65\n88 121\n5 14\n29 58\n19 46\n30 48\n32 60\n0 13\n84 95\n72 76\n94 108\n91 113\n5 7\n2 9\n50 82\n91 117\n18 29\n76 88\n99 127\n59 89\n48 55\n29 41\n7 36\n63 72\n60 70\n24 44\n84 86\n36 56\n65 85\n40 52\n47 55",out:"10"},{in:"60\n6 11\n5 11\n17 20\n13 19\n7 13\n10 11\n3 8\n15 17\n4 9\n9 12\n17 19\n1 7\n17 22\n15 21\n2 5\n15 16\n12 19\n1 7\n6 8\n13 17\n16 22\n4 9\n14 20\n4 9\n9 15\n16 19\n14 19\n13 15\n18 23\n5 7\n9 15\n5 7\n12 18\n19 22\n3 6\n4 10\n19 23\n5 9\n3 8\n7 8\n20 23\n4 6\n1 3\n5 9\n19 21\n2 6\n6 10\n4 5\n5 12\n7 8\n12 13\n17 21\n18 21\n10 13\n16 19\n19 22\n6 7\n5 8\n17 24\n15 20",out:"19"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> s(n), e(n);\n    for (int i = 0; i < n; i++) cin >> s[i] >> e[i];\n    // số phòng cần = số cuộc họp diễn ra đồng thời nhiều nhất\n    cout << 0 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>{const s=(i*37)%(2*n);return s+" "+(s+n)}).join("\n"),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"Đếm số cuộc họp chứa từng thời điểm bắt đầu tốn O(n²)."},py:{start:"n = int(input())\ns, e = [], []\nfor _ in range(n):\n    a, b = map(int, input().split())\n    s.append(a)\n    e.append(b)\n# số phòng cần = số cuộc họp diễn ra đồng thời nhiều nhất\nprint(0)",hints:["Số phòng cần = số cuộc họp diễn ra cùng lúc nhiều nhất; mức chồng lấn lớn nhất đạt tại một thời điểm bắt đầu nào đó.","Sắp riêng giờ bắt đầu và giờ kết thúc; quét giờ bắt đầu tăng dần, trước đó trả lại mọi phòng có e ≤ s hiện tại. Hoặc dùng heapq giữ giờ kết thúc.","Trâu bò để đối chiếu: với mỗi s_i, đếm số cuộc họp chứa s_i — O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] s = new long[n], e = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            s[i] = t[0];\n            e[i] = t[1];\n        }\n        // số phòng cần = số cuộc họp diễn ra đồng thời nhiều nhất\n        Console.WriteLine(0);\n    }\n}",hints:["Số phòng cần = số cuộc họp diễn ra cùng lúc nhiều nhất; mức chồng lấn lớn nhất đạt tại một thời điểm bắt đầu nào đó.","Sắp riêng giờ bắt đầu và giờ kết thúc; quét giờ bắt đầu tăng dần, trước đó trả lại mọi phòng có e ≤ s hiện tại (hai con trỏ).","Trâu bò để đối chiếu: với mỗi s_i, đếm số cuộc họp chứa s_i — O(n²)."]}},{t:"Chuỗi tăng trưởng dài nhất",d:"Doanh thu n tháng là a_1 … a_n. Chọn ra một số tháng (giữ nguyên thứ tự, không cần liền nhau) sao cho doanh thu tăng ngặt. Nhiều nhất chọn được bao nhiêu tháng? Đầu vào: n (1 ≤ n ≤ 2·10^5) rồi n số (|a_i| ≤ 10^9). Đầu ra: một số.",tests:[{in:"8\n3 1 4 1 5 9 2 6",out:"4"},{in:"1\n5",out:"1"},{in:"3\n5 5 5",out:"1"},{in:"4\n1 2 3 4",out:"4"},{in:"4\n4 3 2 1",out:"1"},{in:"50\n-558653348 826841159 -487727921 -43761263 -854929805 560081474 -556726228 -58946785 -937877654 -885978012 480239414 165510861 619762286 835483330 285127789 -186648827 -18789680 -122722532 -908268763 64520549 488856854 -437110456 28424598 336329933 -131048496 -28956126 993388596 202233022 -592971349 -967578159 998733871 535116277 486152316 906519548 -188406503 531358062 952332371 -794293190 950463530 -963846292 408965173 -827468089 -238959920 -141647272 406637523 32426060 -903855182 -430910439 -87456436 -905178308",out:"9"},{in:"60\n10 1 2 7 10 9 3 9 3 0 5 9 3 1 3 3 5 0 2 3 4 8 0 6 6 9 8 6 9 0 5 3 9 0 4 8 1 2 1 3 10 1 5 8 3 3 4 6 6 7 3 8 6 6 4 3 4 10 6 4",out:"10"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    // duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\n    cout << 0 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000003).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"QHĐ xét mọi j < i cho mỗi i tốn O(n²)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\nprint(0)",hints:["QHĐ O(n²) quá chậm với n = 2·10^5. Giữ duoi[k] = phần tử cuối nhỏ nhất của một dãy tăng độ dài k + 1; duoi luôn tăng.","Với mỗi x: k = bisect_left(duoi, x). k = len(duoi) thì nối x; không thì duoi[k] = x.","Tăng ngặt nên bisect_left; nếu cho phép bằng nhau thì bisect_right. Đáp án là len(duoi)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        // duoi[k]: phần tử cuối nhỏ nhất của một dãy tăng dài k + 1\n        Console.WriteLine(0);\n    }\n}",hints:["QHĐ O(n²) quá chậm với n = 2·10^5. Giữ duoi[k] = phần tử cuối nhỏ nhất của một dãy tăng độ dài k + 1; duoi luôn tăng.","Với mỗi x: tìm nhị phân vị trí đầu tiên có giá trị ≥ x. Bằng Count thì Add; không thì thay.","Tự viết hàm tìm nhị phân trên List<long> (List.BinarySearch trả về số âm khi không thấy, dễ nhầm)."]}},{t:"Robot trong kho hàng",d:"Sơ đồ kho là lưới R × C: “.” là lối đi, “#” là kệ hàng, “S” là vị trí robot, “E” là cửa xuất (mỗi loại S, E đúng một ô). Mỗi bước robot sang một ô kề cạnh không phải kệ. Ít nhất bao nhiêu bước để tới E? In −1 nếu không tới được. Đầu vào: R C (1 ≤ R, C ≤ 1000) rồi R dòng. Đầu ra: một số.",tests:[{in:"4 4\nS.#.\n..#.\n...E\n#...",out:"5"},{in:"1 2\nSE",out:"1"},{in:"1 3\nS#E",out:"-1"},{in:"3 1\nS\n#\nE",out:"-1"},{in:"4 4\nS...\n###.\nE...\n....",out:"8"},{in:"8 10\nS..#..#.#.\n.........#\n##..#....#\n....#.#...\n.#........\n..#...#.#.\n..###..#..\n#..###..#E",out:"16"},{in:"12 9\nS.......#\n##.###...\n##....##.\n###....##\n....##...\n..##...#.\n.........\n.#..#..#.\n...#.#...\n...##...#\n..##.#...\n........E",out:"19"},{in:"6 6\nS##.#.\n..#...\n......\n.##...\n##..##\n.#..#E",out:"-1"}],start:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int R, C;\n    cin >> R >> C;\n    vector<string> g(R);\n    for (auto& row : g) cin >> row;\n    // BFS từ ô S; d[r][c] = số bước, -1 = chưa tới\n    cout << -1 << \"\\n\";\n    return 0;\n}",py:{start:"R, C = map(int, input().split())\ng = [input() for _ in range(R)]\n# BFS từ ô S; d[r][c] = số bước, -1 = chưa tới\nprint(-1)",hints:["“Ít bước nhất”, mọi bước như nhau: BFS từ ô S. d[r][c] = −1 nghĩa là chưa tới; E không tới được thì d giữ −1.","Bốn hướng: duyệt các cặp (dr, dc). Kiểm tra ra ngoài lưới trước khi đọc g[nr][nc].","Dùng list làm hàng đợi và duyệt bằng for (list dài thêm trong lúc duyệt), hoặc collections.deque."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] rc = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int R = rc[0], C = rc[1];\n        string[] g = new string[R];\n        for (int r = 0; r < R; r++) g[r] = Console.ReadLine();\n        // BFS từ ô S; d[r][c] = số bước, -1 = chưa tới\n        Console.WriteLine(-1);\n    }\n}",hints:["“Ít bước nhất”, mọi bước như nhau: BFS từ ô S. d[r][c] = −1 nghĩa là chưa tới; E không tới được thì d giữ −1.","Bốn hướng: hai mảng dr, dc. Kiểm tra ra ngoài lưới trước khi đọc g[nr][nc].","Hàng đợi là List<int> lưu r · C + c, duyệt bằng chỉ số i (hoặc Queue<int>)."]}}]);

